(3, 'wild-love-leopard-set', 'Wild Love Leopard Set', 'Experience effortless style with our ultra-soft Printed Sets. Lightweight, stretchable, and wire-free—perfect for all-day wear without compromising on the trend.', NULL, 2500.00, NULL, 6, 14, 'LIMITED EDITION', '[\"Small\",\"Medium\",\"Large\"]', '[{\"name\":\"Choco brown\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778583958\\/products\\/xtgzieamfzokwiov8nh2.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778583958\\/products\\/e6oz0l8xno0gviqs7fkm.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778583958\\/products\\/i3vhvuee9cddyujtzsp9.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584028\\/products\\/kf8qouwg1rjsznfw9h2u.jpg\"]}]', '2026-05-11 22:20:59', 5, '[{\"color\":\"Choco brown\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778583958\\/products\\/xtgzieamfzokwiov8nh2.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778583958\\/products\\/e6oz0l8xno0gviqs7fkm.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778583958\\/products\\/i3vhvuee9cddyujtzsp9.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584028\\/products\\/q0boiloc4gllakvqdolm.jpg\"],\"sizes\":[{\"size\":\"Small\",\"stock\":2},{\"size\":\"Medium\",\"stock\":1},{\"size\":\"Large\",\"stock\":3}]}]', 0),
(4, 'wild-heart-seamless-set', 'Wild Heart Seamless Set', 'Experience cloud-like ease with the Wild Heart Set. Designed with a seamless finish and wire-free support, this printed duo ensures a smooth silhouette and all-day freshness in four dreamy shades.', NULL, 2100.00, NULL, 12, 14, 'EXCLUSIVE', '[\"Small\",\"Medium\",\"Large\"]', '[{\"name\":\"Beige\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584852\\/products\\/cf8vbxgaf3dvd7osujdd.jpg\"]},{\"name\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/hxi5spqgaueksx1rfbj6.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/tybecgmuddmiqgjksjzy.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/ddbpgfrdvmdgacnsognb.jpg\"]},{\"name\":\"Brown\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/qm3z43goknx1wh5luhda.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/h0bf0vaymwuwepyg2p6a.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/pkblaq24ddy7xsm5e6t9.jpg\"]}]', '2026-05-12 11:17:09', 5, '[{\"color\":\"Beige\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584852\\/products\\/cf8vbxgaf3dvd7osujdd.jpg\"],\"sizes\":[{\"size\":\"Small\",\"stock\":4}]},{\"color\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/m9cb5yyp96rl71cxuuzv.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/uxceumvzao2bufwjyfkp.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/zwhcekpk801oc0r8izuw.jpg\"],\"sizes\":[{\"size\":\"Medium\",\"stock\":4}]},{\"color\":\"Brown\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/quxwt5adanuyuzqfsbwc.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/lemu4qfsdm1ynqj11tea.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778584946\\/products\\/w9a9ikawxs7utwabfi6g.jpg\"],\"sizes\":[{\"size\":\"Large\",\"stock\":4}]}]', 0),
(5, 'geometric-noir-bodystocking', 'Geometric Noir Bodystocking', 'Define your curves with our Geometric Noir Bodystocking. Crafted from high-stretch fishnet with a striking criss-cross pattern and halter neck finish, this full-body piece offers a seamless, bold look under any outfit or as a standalone statement.', NULL, 1300.00, NULL, 1, 6, '', '[\"Free Size\"]', '[{\"name\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778586735\\/products\\/ulzw4rnjt7ixjokhuehy.jpg\"]}]', '2026-05-12 11:46:57', 5, '[{\"color\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778586735\\/products\\/ulzw4rnjt7ixjokhuehy.jpg\"],\"sizes\":[{\"size\":\"Free Size\",\"stock\":1}]}]', 0),
(6, 'greek-maze-bodystocking', 'Greek Maze Bodystocking', 'Unveil elegance with our Greek Maze Bodystocking. Featuring an intricate, high-definition geometric pattern and a sleek halter-neck cut, this full-body piece is crafted from premium stretch mesh to offer a flawless, second-skin fit. A perfect blend of art and allure for your collection.', '', 1300.00, NULL, 1, 6, '', '[\"Free Size\"]', '[{\"name\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587224\\/products\\/jcrosmmefwkfn8vcrehh.jpg\"]}]', '2026-05-12 12:00:25', 5, '[{\"color\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587224\\/products\\/sk1or09bl4e0wylmjggn.jpg\"],\"sizes\":[{\"size\":\"Free Size\",\"stock\":1}]}]', 0),
(7, 'floral-mesh-enchant-bodystocking', 'Floral Mesh Enchant Bodystocking', 'Elevate your wardrobe with the Floral Mesh Enchant Bodystocking. A masterpiece of intricate floral lace combined with classic fishnet mesh, this full-body piece features a stylish halter neckline and a flattering high-waist illusion. Designed with ultra-stretch fabric, it perfectly contours your silhouette for a bold, sophisticated look.', '', 1300.00, NULL, 1, 6, '', '[\"Free Size\"]', '[{\"name\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587537\\/products\\/jgcvu2ds5xizoskqqhuu.jpg\"]}]', '2026-05-12 12:05:37', 5, '[{\"color\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587536\\/products\\/iftrdyjwsgwdnmlqxrsy.jpg\"],\"sizes\":[{\"size\":\"Free Size\",\"stock\":1}]}]', 0),
(8, 'v-line-linear-bodystocking', 'V-Line Linear Bodystocking', 'Sculpt your silhouette with our V-Line Linear Bodystocking. Featuring a unique combination of diagonal stripes and precision chevron mesh, this full-body piece is designed to elongate and flatter your curves. The sleek halter-neck and open-back detail offer ultimate style without compromising on the buttery-soft, ultra-stretch comfort you love.', '', 1300.00, NULL, 1, 6, '', '[\"Free Size\"]', '[{\"name\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587671\\/products\\/nmzvrgvsghbskoejhnjp.jpg\"]}]', '2026-05-12 12:07:52', 5, '[{\"color\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587671\\/products\\/izbmf4emfry3jhdlnhbj.jpg\"],\"sizes\":[{\"size\":\"Free Size\",\"stock\":1}]}]', 0),
(9, 'eclipse-sleeved-bodystocking', 'Eclipse Sleeved Bodystocking', 'Reinvent your style with the Eclipse Sleeved Bodystocking. A rare combination of sophisticated 3/4 sleeves and bold circular mesh patterns, this full-body piece offers a seamless, high-fashion look. Crafted from ultra-stretch, breathable fabric, it contours every curve while providing a smooth, flawless finish from shoulder to toe.', '', 1300.00, NULL, 1, 6, '', '[\"Free Size\"]', '[{\"name\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587780\\/products\\/swkwq0wzdqueym9dakkf.jpg\"]}]', '2026-05-12 12:09:41', 5, '[{\"color\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587780\\/products\\/lpuarx8yn5w96gfja3bk.jpg\"],\"sizes\":[{\"size\":\"Free Size\",\"stock\":1}]}]', 0),
(10, 'luxe-cold-shoulder-bodystocking', 'Luxe Cold-Shoulder Bodystocking', 'Drape yourself in sophistication with our Luxe Cold-Shoulder Bodystocking. A perfect fusion of high-fashion and comfort, this piece features trendy cold-shoulder sleeves and an intricate floral lace pattern that beautifully contours your curves. Designed with a unique garter-style illusion and an open-back finish, it’s the ultimate statement piece for a bold, seamless, and elegant silhouette.', '', 1300.00, NULL, 1, 6, '', '[\"Free Size\"]', '[{\"name\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587969\\/products\\/pxdcbnajhvdsdqc83xx9.jpg\"]}]', '2026-05-12 12:12:52', 5, '[{\"color\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778587969\\/products\\/lkmll5yhyvjqvptxljld.jpg\"],\"sizes\":[{\"size\":\"Free Size\",\"stock\":1}]}]', 0),
(11, 'velocity-zip-front-sports-bra', 'Velocity Zip-Front Sports Bra', 'Elevate your workout experience with the Velocity Zip-Front Sports Bra. Engineered for high-impact support, this bra features a convenient front-zip closure for easy wear and a stylish cross-back design for maximum stability and breathability. Crafted from premium, moisture-wicking fabric with breathable mesh panels, it ensures you stay cool and comfortable—whether you\'re at the gym or on a morning run.', NULL, 2000.00, NULL, 7, 15, '', '[\"Medium\",\"Large\"]', '[{\"name\":\"Purple\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778594764\\/products\\/uvjavhgcklw6ly0xvze9.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778594764\\/products\\/ojjen42ywjk0gyuzy87h.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778594764\\/products\\/ptgw6tn9fauf9tgcftzp.jpg\"]}]', '2026-05-12 14:03:03', 5, '[{\"color\":\"Purple\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778594764\\/products\\/fvo8qujowili4knhdp1g.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778594764\\/products\\/qtpd3rn80oyzgtxyj38p.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778594764\\/products\\/gcss2duoyteth4953cw9.jpg\"],\"sizes\":[{\"size\":\"Medium\",\"stock\":4},{\"size\":\"Large\",\"stock\":3}]}]', 0),
