(13, 'velocity-zip-front-sports-bra-2', 'Velocity Zip-Front Sports Bra', 'Elevate your workout experience with the Velocity Zip-Front Sports Bra. Engineered for high-impact support, this bra features a convenient front-zip closure for easy wear and a stylish cross-back design for maximum stability and breathability. Crafted from premium, moisture-wicking fabric with breathable mesh panels, it ensures you stay cool and comfortable—whether you\'re at the gym or on a morning run.', '', 2000.00, NULL, 2, 15, '', '[\"Medium\",\"XL\"]', '[{\"name\":\"Light Green\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778595118\\/products\\/ehgorlebwcs62emlicwn.jpg\"]}]', '2026-05-12 14:11:59', 5, '[{\"color\":\"Light Green\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778595118\\/products\\/usl1tag5qw0wmxqt2dlu.jpg\"],\"sizes\":[{\"size\":\"Medium\",\"stock\":1},{\"size\":\"XL\",\"stock\":1}]}]', 0),
(14, 'velocity-zip-front-sports-bra-3', 'Velocity Zip-Front Sports Bra', 'Elevate your workout experience with the Velocity Zip-Front Sports Bra. Engineered for high-impact support, this bra features a convenient front-zip closure for easy wear and a stylish cross-back design for maximum stability and breathability. Crafted from premium, moisture-wicking fabric with breathable mesh panels, it ensures you stay cool and comfortable—whether you\'re at the gym or on a morning run.', '', 2000.00, NULL, 0, 15, '', '[\"Small\",\"Medium\",\"Large\",\"XL\",\"XXL\",\"XXXL\"]', '[{\"name\":\"Silver\",\"images\":[]}]', '2026-05-12 14:13:34', 5, '[{\"color\":\"Silver\",\"images\":[],\"sizes\":[{\"size\":\"Small\",\"stock\":0},{\"size\":\"Medium\",\"stock\":0},{\"size\":\"Large\",\"stock\":0},{\"size\":\"XL\",\"stock\":0},{\"size\":\"XXL\",\"stock\":0},{\"size\":\"XXXL\",\"stock\":0}]}]', 0),
(15, 'elegance-front-open-bra', 'Elegance Front Open Bra', 'Premium quality seamless support bra with front hook closure design. Soft, stretchable and breathable fabric provides maximum comfort for daily wear. Wide straps and full coverage support help maintain shape and give a comfortable fit all day long. Elegant lace pattern adds a stylish and modern look.', '', 1500.00, NULL, 4, 16, 'TRENDING', '[\"Large\",\"XL\",\"XXL\",\"XXXL\",\"Medium\",\"Small\"]', '[{\"name\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778613093\\/products\\/lnlwl1f1eubzpmbwryie.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778613093\\/products\\/gbjtw0n22dfwn44eqmi7.jpg\"]},{\"name\":\"\",\"images\":[]},{\"name\":\"\",\"images\":[]}]', '2026-05-12 19:11:33', 4, '[{\"color\":\"Black\",\"images\":[\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778613092\\/products\\/iyq5dcqrjupsm4xakayw.jpg\",\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778613093\\/products\\/yydtzsdltv6pftwgplvb.jpg\"],\"sizes\":[{\"size\":\"Large\",\"stock\":1},{\"size\":\"XL\",\"stock\":3},{\"size\":\"XXL\",\"stock\":0},{\"size\":\"XXXL\",\"stock\":0},{\"size\":\"Medium\",\"stock\":0},{\"size\":\"Small\",\"stock\":0}]},{\"color\":\"\",\"images\":[],\"sizes\":[]},{\"color\":\"\",\"images\":[],\"sizes\":[]}]', 0);

